function controlSettingsPane(){const candidates=controlCandidates();return `<div class="card"><h2>دامنه کنترل موجودی</h2><p>تعیین دامنه، مقدار یا محل تاریخی افتتاحیه را عوض نمی‌کند. مبنای کل باید تمام انبار، آشپزخانه، بار و سایر محل‌ها را پوشش دهد.</p><div class="form-grid"><div class="field"><label>حالت کنترل</label><select id="rayoControlMode"><option value="locations" ${!unifiedMode()?'selected':''}>تفکیکی محل‌ها</option><option value="unified" ${unifiedMode()?'selected':''}>کنترل یکپارچه کل رایو</option></select></div><div class="field"><label>افتتاحیه موجود برای تعیین دامنه کل</label><select id="rayoControlOpening"><option value="">فقط تغییر حالت؛ بدون تبدیل افتتاحیه</option>${candidates.map(c=>`<option value="${E(c.key)}">${E(c.date)} — ${E(locationName(c.locationId))} — ${E(c.records.map(r=>r.id).join('، '))}</option>`).join('')}</select></div><div class="field"><label>زمان واقعی افتتاحیه انتخابی</label><select id="rayoControlBoundary"><option value="START">ابتدای روز؛ عملیات همان روز محاسبه شود</option><option value="END">پایان روز؛ عملیات از روز بعد محاسبه شود</option></select></div></div><p>${candidates.length?'برای افتتاحیه اول شهریور، سند موجود را انتخاب کنید؛ مقدارها دوباره وارد نمی‌شوند.':'افتتاحیه قابل تبدیل موجود نیست؛ شمارش کل جدید از تب انبارگردانی ثبت می‌شود.'}</p><div class="v1012-actions"><button class="btn btn-primary" onclick="RayoInventoryV10.previewControlChange()">پیش‌نمایش تغییر</button><button class="btn" onclick="RayoInventoryV10.previewControlRollback()">پیش‌نمایش بازگردانی آخرین تغییر</button></div><p id="rayoControlStatus" role="status"></p></div>`}
