function unifiedCountPane(){return `<div class="card"><h2>شمارش کل رایو</h2><p class="hint">تمام موجودی انبار، آشپزخانه، بار و سایر محل‌ها را یکجا بشمارید. صفر یعنی شمارش شده و ناموجود؛ خانه خالی یعنی شمارش نشده و پوشش ناقص. شمارش عادی پایان روز است. افتتاحیه ابتدای روز، عملیات همان روز را هم حساب می‌کند.</p><form onsubmit="event.preventDefault();RayoInventoryV10.saveUnifiedCount()"><fieldset id="rayoWholeFields" style="border:0;padding:0;min-width:0"><div class="form-grid"><div class="field"><label>تاریخ</label><input id="rayoWholeDate" data-jalali="1" value="${E(today())}"></div><div class="field"><label>نوع مبنا</label><select id="rayoWholeKind"><option value="END">شمارش دوره‌ای پایان روز</option><option value="START">افتتاحیه ابتدای روز</option></select></div><div class="field full"><label>شرح شمارش</label><input id="rayoWholeNote"></div></div><div class="table-wrap" style="max-height:60vh"><table class="data-table"><thead><tr><th>قلم</th><th>واحد</th><th>موجودی واقعی کل</th></tr></thead><tbody>${controlItems().map(i=>`<tr><td>${E(i.name)} <small>${E(i.code||'')}</small></td><td>${E(ingredientUnit(i))}</td><td><input data-whole-count="${E(i.id)}" inputmode="decimal" placeholder="شمارش نشده" aria-label="موجودی کل ${E(i.name)}"></td></tr>`).join('')}</tbody></table></div><button class="btn btn-primary" type="submit">ذخیره و تأیید شمارش کل</button><p id="rayoWholeStatus" role="status"></p></fieldset></form></div>`}
