function recordMovementStatus(w){const rs=S(w?.reviewStatus);if(w?.status==='void'||rs==='ردشده')return 'void';if(w?.reportedByPersonnelId&&!['تأییدشده','ضایعات ثبت‌شده','موجه','بسته‌شده'].includes(rs))return 'pending';return 'posted'}
