function closedMetrics(from,to){
 const snapshot=A(inv?.periodClosures).filter(x=>x.status==='closed'&&D(x.from)===D(from)&&D(x.to)===D(to)&&x.metrics&&Array.isArray(x.lines)).sort((a,b)=>S(b.closedAt).localeCompare(S(a.closedAt)))[0];
 if(!snapshot)return null;
 const m={...snapshot.metrics},lines=JSON.parse(JSON.stringify(snapshot.lines)),auth=m.authorized??m.auth??0,missing=lines.reduce((n,l)=>n+N(l.missingQty)*N(l.unitCost),0),sales=m.sales;
 return{...m,from,to,lines,auth,missing,fromSnapshot:true,salesAvailable:Number.isFinite(sales),salesSource:'نسخه قطعی دوره بسته',available:m.openingValue+m.purchases,wastePct:sales?m.waste/sales*100:0,wastePctStandard:m.standard?m.waste/m.standard*100:0,wasteShareOfMaterialOut:m.standard+m.waste+auth?m.waste/(m.standard+m.waste+auth)*100:0,variancePct:sales?m.unexplained/sales*100:0,wasteQuantities:wasteQuantitySummary(lines),wasteEventCount:null};
}
function periodMetrics(from,to){const closed=closedMetrics(from,to);if(closed)return closed;if(unifiedMode())return unifiedPeriodMetrics(from,to);const ings=A(pricing.ingredients).filter(i=>i.itemType!=='NON_STOCK'),locs=activeLocations();let openingValue=0,purchases=0,standard=0,waste=0,missing=0,auth=0,closingValue=0,priceEffect=0,itemSales=0,itemSalesCount=0,covered=0,totalPairs=0;const lines=[];for(const i of ings){const c=weightedCost(i.id,from,to);priceEffect+=c.priceEffect;purchases+=c.purchaseValue;let openQty=0,closeQty=0,stdQty=0,wasteQty=0,missingQty=0,authQty=0,coveragePairs=0;for(const l of locs){const op=positionBeforeDate(i.id,l.id,from);openQty+=op.quantity;const closeCount=latestApprovedCount(i.id,l.id,to,to);totalPairs++;if(closeCount){coveragePairs++;covered++}closeQty+=positionAtLocation(i.id,l.id,to).quantity;stdQty+=salesQtyForIngredientLocation(i.id,l.id,from,to,true);for(const m of A(inv.inventoryMovements)){if(!movementActive(m)||m.ingredientId!==i.id||m.fromLocationId!==l.id||!inRange(m.date,from,to))continue;if(WASTE_TYPES.has(m.movementType))wasteQty+=N(m.quantity);if(m.movementType==='MISSING')missingQty+=N(m.quantity);if(AUTH_TYPES.has(m.movementType))authQty+=N(m.quantity)}}if([openQty,closeQty,stdQty,wasteQty,missingQty,authQty,c.purchaseQty].every(x=>x===0))continue;const unit=c.unitCost,openVal=openQty===0?0:openQty*c.openingUnitCost,closeVal=closeQty*unit;openingValue+=openVal;closingValue+=closeVal;standard+=stdQty*unit;waste+=wasteQty*unit;missing+=missingQty*unit;auth+=authQty*unit;const actual=openVal+c.purchaseValue-closeVal,unexplained=actual-(stdQty+wasteQty+missingQty+authQty)*unit;lines.push({ingredientId:i.id,name:i.name,unit:i.recipeUnit||'واحد',openQty,purchaseQty:c.purchaseQty,stdQty,wasteQty,missingQty,authQty,closeQty,unitCost:unit,actual,unexplained,coveragePairs,totalLocationPairs:locs.length})}
 for(const sp of A(inv.salesPeriods)){if(sp.status==='void')continue;for(const l of A(sp.lines)){const dt=saleDate(sp,l);if(inRange(dt,from,to)){itemSales+=N(l.quantity)*N(l.salePriceToman||menuItem(l.menuItemId)?.currentPriceToman);itemSalesCount++}}}const cashSales=cashSalesToman(from,to),salesAvailable=cashSales.available||itemSalesCount>0,sales=cashSales.available?cashSales.value:itemSales,salesSource=cashSales.available?'گزارش صندوق':itemSalesCount>0?'ریز فروش سپیدز':'داده فروش دوره آماده نیست';const actualCogs=openingValue+purchases-closingValue,unexplained=actualCogs-standard-waste-missing-auth,materialOut=standard+waste+auth;const approvedWasteEvents=A(inv.wasteRecords).filter(r=>r.status!=='void'&&r.eventType!=='MISSING'&&inRange(r.date,from,to)&&(!r.reportedByPersonnelId||['تأییدشده','ضایعات ثبت‌شده','موجه','بسته‌شده'].includes(S(r.reviewStatus)))).length;return{from,to,openingValue,purchases,available:openingValue+purchases,standard,waste,missing,auth,closingValue,actualCogs,unexplained,priceEffect,sales,salesAvailable,salesSource,itemSales,standardPct:sales?standard/sales*100:0,actualPct:sales?actualCogs/sales*100:0,grossProfit:sales-actualCogs,wastePct:sales?waste/sales*100:0,wastePctStandard:standard?waste/standard*100:0,wasteShareOfMaterialOut:materialOut?waste/materialOut*100:0,variancePct:sales?unexplained/sales*100:0,coverage:totalPairs?covered/totalPairs*100:0,wasteQuantities:wasteQuantitySummary(lines),wasteEventCount:approvedWasteEvents,lines}}
function monthRange(offset=0){const t=D(today()),m=t.match(/(\d{4})\/(\d{2})/);if(!m)return{key:'',from:'',to:''};let y=+m[1],mo=+m[2]-offset;while(mo<=0){mo+=12;y--}while(mo>12){mo-=12;y++}const key=`${y}/${String(mo).padStart(2,'0')}`;return{key,from:`${key}/01`,to:offset===0?t:`${key}/31`}}
